// @ts-nocheck
// ===== UB-MC-CM-008 (Core Molding) · Scan Tag PLC Mitsubishi =====
// หา PLC + protocol เอง (Modbus TCP 502 · SLMP/MC 3E Binary · 3E ASCII · 4E Binary · SLMP UDP 8001/8002) แล้วอ่านทั้งช่วงทุก SCAN_SEC วินาที
//   Modbus : Holding Register (HR) / Input Register (IR) / Coil (CO) / Discrete Input (DI) · MC : D / W / M / X / Y / B
// จดว่า register ไหน "เปลี่ยน" → ใช้หา Tag ยอดผลิต (Counter) / สถานะ / Cycle time / ชื่อรุ่น โดยดูคู่กับหน้าจอ HMI
//
// วิธีใช้:  1) ใส่ HOST (IP PLC) ถ้ารู้ · เว้นว่าง = หาให้เองในวงเดียวกับกล่อง IoT (eth0) + 192.168.3.x (ค่าโรงงาน Mitsubishi)
//          2) Deploy → ให้เครื่องเดินสัก 2–5 นาที → กดปุ่ม "สรุปผล" ดูใน Debug
//          3) เทียบกับ HMI: ยอดที่เพิ่ม +1 ทุกรอบ = Counter · ค่า 0/1/2/3 ที่เปลี่ยนตอนเครื่องหยุด/เดิน = Status
// Output 1 = สรุป Tag ที่เปลี่ยน (เรียงตามน่าสนใจ) · Output 2 = ค่าไม่เป็น 0 ทั้งหมด / ข้อความ ASCII · Output 3 = ผลค้นหา / error
const MACHINE = "UB-MC-CM-008";
let   HOST    = "192.168.3.100";        // *** IP PLC UB-MC-CM-008 (2026-10-28) · ว่าง "" = หาเองใน 192.168.0.x / 192.168.3.x / วง eth0 ***
const UDP_PORTS = [8001, 8002, 5000, 5001];   // SLMP UDP (เครื่องนี้ตั้งไว้ 8001 / 8002 ใน GX Works3)
const PORTS   = [502, 5000, 5001, 5002, 5003, 5004, 5005, 5006, 5007, 5010, 5011, 5012, 5100, 1025, 1026, 4999, 8000];
const TMO     = 2500;
const SCAN_SEC = 5;                     // อ่านทั้งช่วงทุก 5 วินาที (inject ส่งทุก 1 วินาที)
const BLOCK   = 900;                    // word ต่อ 1 คำสั่ง (MC 3E สูงสุด 960)
// ช่วงที่สแกน (word) · bit device อ่านเป็น word ละ 16 bit · ถ้า PLC ตอบว่าเกินช่วง จะหยุดที่ตรงนั้นเอง
const AREAS_MC = [
    { dev: "D", code: 0xA8, asc: "D*", words: 8000, bit: false },   // D0–D7999
    { dev: "W", code: 0xB4, asc: "W*", words: 512,  bit: false, hex: true },
    { dev: "M", code: 0x90, asc: "M*", words: 500,  bit: true },    // M0–M7999
    { dev: "X", code: 0x9C, asc: "X*", words: 64,   bit: true, hex: true },
    { dev: "Y", code: 0x9D, asc: "Y*", words: 64,   bit: true, hex: true },
    { dev: "B", code: 0xA0, asc: "B*", words: 64,   bit: true, hex: true }
];
// Modbus TCP (port 502) · FX5 ค่าเริ่มต้นมักเป็น HR0 = D0 · Coil = Y / M · DI = X (ขึ้นกับ MODBUS Device Assignment ใน GX Works3)
const AREAS_MB = [
    { dev: "HR", fc: 3, words: 8000, bit: false },   // Holding Register 0–7999
    { dev: "IR", fc: 4, words: 1024, bit: false },   // Input Register 0–1023
    { dev: "CO", fc: 1, words: 1024, bit: true },    // Coil 0–16383 (เก็บเป็น word ละ 16 bit)
    { dev: "DI", fc: 2, words: 256,  bit: true }     // Discrete Input 0–4095
];
const isMB = cfg => !!cfg && /^MB/.test(cfg.proto);
let AREAS = isMB(context.get("cfg")) ? AREAS_MB : AREAS_MC;

if (msg.topic === "reset") { context.set("st", null); node.status({ fill: "grey", shape: "ring", text: "ล้างสถิติแล้ว" }); return null; }
if (msg.topic === "summary") { const s = context.get("st"); if (!s) { node.warn("ยังไม่มีข้อมูล"); return null; } node.send(summary(s)); return null; }
if (msg.topic === "rehost") { context.set("cfg", null); context.set("host", null); context.set("retryAt", 0); }
if (context.get("busy")) return null;
if (Date.now() - (context.get("lastScan") || 0) < SCAN_SEC * 1000 && msg.topic !== "rehost") return null;
context.set("busy", true);

// ---------- การเชื่อมต่อแบบค้างไว้ (PLC รับทีละไม่กี่ connection) ----------
function getConn(host, port, udp) {
    let c = context.get("conn");
    if (c && c.host === host && c.port === port && !!c.udp === !!udp && !c.dead) return Promise.resolve(c);
    if (c && c.sock) { try { c.sock.destroy(); } catch (e) {} }
    if (udp) return new Promise(res => {      // SLMP แบบ UDP (FX5 ตั้ง SLMP Connection Module เป็น UDP 8001 / 8002)
        const u = dgram.createSocket("udp4");
        c = { host, port, udp: true, buf: Buffer.alloc(0), wait: null, dead: false, ready: false,
              sock: { write: f => u.send(f, port, host), destroy: () => { try { u.close(); } catch (e) {} } } };
        const kill = (why) => { c.dead = true; c.why = c.why || why; if (c.wait) { const w = c.wait; c.wait = null; w({ err: why }); } };
        u.on("message", d => { c.buf = Buffer.concat([c.buf, d]); if (c.wait) c.wait(); });
        u.on("error", e => kill(e.code || e.message));
        u.bind(() => { c.ready = true; res(c); });
        context.set("conn", c);
    });
    return new Promise(res => {
        const s = new net.Socket();
        c = { host, port, sock: s, buf: Buffer.alloc(0), wait: null, dead: false, ready: false };
        const kill = (why) => { c.dead = true; c.why = c.why || why; if (c.wait) { const w = c.wait; c.wait = null; w({ err: why }); } };
        s.setNoDelay(true); s.setKeepAlive(true, 10000);
        s.on("data", d => { c.buf = Buffer.concat([c.buf, d]); if (c.wait) c.wait(); });
        s.on("error", e => kill(e.code || e.message));
        s.on("close", () => kill("closed"));
        const t = setTimeout(() => { if (!c.ready) { kill("connect timeout"); s.destroy(); res(c); } }, TMO);
        s.connect(port, host, () => { clearTimeout(t); c.ready = true; res(c); });
        context.set("conn", c);
    });
}
function ask(c, frame, need) {
    return new Promise(res => {
        if (c.dead || !c.ready) return res({ err: c.why === "closed" ? "PLC ตัดสาย" : "ไม่ได้เชื่อมต่อ" });
        c.buf = Buffer.alloc(0);
        const t = setTimeout(() => { c.wait = null; c.dead = true; try { c.sock.destroy(); } catch (e) {} res({ err: "ไม่ตอบ (timeout)" }); }, TMO);
        c.wait = (fail) => {
            if (fail && fail.err) { clearTimeout(t); return res({ err: fail.err === "closed" ? "PLC ตัดสายหลังส่งคำสั่ง" : fail.err }); }
            if (need(c.buf)) { clearTimeout(t); c.wait = null; const b = c.buf; c.buf = Buffer.alloc(0); res({ buf: b }); }
        };
        c.sock.write(frame);
    });
}
const sleep = ms => new Promise(r => setTimeout(r, ms));
const hx = (v, w) => v.toString(16).toUpperCase().padStart(w, "0");

// ---------- frame อ่านแบบ word (0401 / sub 0000) ----------
function frBin(is4e, area, start, n) {
    const o = is4e ? 4 : 0, b = Buffer.alloc(21 + o);
    if (is4e) { b.writeUInt16LE(0x0054, 0); b.writeUInt16LE(1, 2); b.writeUInt16LE(0, 4); } else b.writeUInt16LE(0x0050, 0);
    b[2 + o] = 0; b[3 + o] = 0xFF; b.writeUInt16LE(0x03FF, 4 + o); b[6 + o] = 0;
    b.writeUInt16LE(12, 7 + o); b.writeUInt16LE(0x0010, 9 + o); b.writeUInt16LE(0x0401, 11 + o); b.writeUInt16LE(0, 13 + o);
    b.writeUIntLE(area.bit ? start * 16 : start, 15 + o, 3); b[18 + o] = area.code; b.writeUInt16LE(n, 19 + o);
    return b;
}
function frAsc(area, start, n) {
    const dn = area.bit ? start * 16 : start;
    const no = area.hex ? hx(dn, 6) : String(dn).padStart(6, "0");
    return Buffer.from("500000FF03FF00" + "0018" + "0010" + "0401" + "0000" + area.asc + no + hx(n, 4), "latin1");
}
let tid = 0;
async function readMb(c, unit, area, start, n) {
    const a0 = area.bit ? start * 16 : start, q = area.bit ? n * 16 : n;
    tid = (tid + 1) & 0xFFFF;
    const r = await ask(c, Buffer.from([tid >> 8, tid & 255, 0, 0, 0, 6, unit, area.fc, (a0 >> 8) & 255, a0 & 255, q >> 8, q & 255]),
                        b => b.length >= 9 && b.length >= 6 + b.readUInt16BE(4));
    if (r.err) return r;
    const b = r.buf;
    if (b[7] & 0x80) return { err: "Modbus exception " + b[8] + (b[8] === 2 ? " (address เกินช่วง)" : b[8] === 1 ? " (ไม่รองรับ function)" : ""), code: b[8] || 99 };
    if (b[7] !== area.fc) return { err: "ไม่ใช่ Modbus (" + b.slice(0, 9).toString("hex") + ")" };
    const v = [];
    if (area.bit) for (let i = 0; i < n; i++) v.push((b[9 + i * 2] || 0) | ((b[10 + i * 2] || 0) << 8));
    else for (let i = 0; i < n; i++) v.push(b.readUInt16BE(9 + i * 2));
    return { v };
}
async function readBlock(c, proto, area, start, n) {
    if (/^MB/.test(proto)) return readMb(c, +proto.slice(2), area, start, n);
    if (proto === "MC3E-ASCII") {
        const r = await ask(c, frAsc(area, start, n), b => b.length >= 18 && b.length >= 18 + parseInt(b.toString("latin1", 14, 18), 16));
        if (r.err) return r;
        const s = r.buf.toString("latin1");
        if (!s.startsWith("D000")) return { err: "ไม่ใช่ MC ASCII (" + s.slice(0, 12) + ")" };
        const end = s.slice(18, 22);
        if (end !== "0000") return { err: "end code 0x" + end, code: parseInt(end, 16) };
        const v = []; for (let i = 0; i < n; i++) v.push(parseInt(s.substr(22 + i * 4, 4), 16)); return { v };
    }
    const is4e = proto === "MC4E", o = is4e ? 4 : 0;
    const r = await ask(c, frBin(is4e, area, start, n), b => b.length >= 11 + o && b.length >= 9 + o + b.readUInt16LE(7 + o));
    if (r.err) return r;
    if (r.buf.readUInt16LE(0) !== (is4e ? 0x00D4 : 0x00D0)) return { err: "ไม่ใช่ MC (" + r.buf.slice(0, 8).toString("hex") + ")" };
    const end = r.buf.readUInt16LE(9 + o);
    if (end !== 0) return { err: "end code 0x" + hx(end, 4), code: end };
    const v = []; for (let i = 0; i < n; i++) v.push(r.buf.readUInt16LE(11 + o + i * 2)); return { v };
}

// ---------- หา PLC ----------
const PROTOS = ["MC3E", "MC3E-ASCII", "MC4E"];
function portOpen(ip, port, ms) {
    return new Promise(res => {
        const s = new net.Socket(); let done = false;
        const fin = ok => { if (done) return; done = true; try { s.destroy(); } catch (e) {} res(ok); };
        s.setTimeout(ms); s.on("timeout", () => fin(false)); s.on("error", () => fin(false));
        s.connect(port, ip, () => fin(true));
    });
}
async function findHosts(report) {
    const own = [], subnets = new Set(["192.168.0", "192.168.3"]);   // 192.168.0.x = วง PLC ที่หน้างานใช้ (เหมือน Seambuffing)
    const ifs = os.networkInterfaces();
    for (const k of Object.keys(ifs)) for (const a of ifs[k] || []) {
        if (a.family !== "IPv4" && a.family !== 4 || a.internal) continue;
        own.push(a.address);
        const p = a.address.split(".");
        if (!/^(10\.121|192\.168\.33|192\.168\.100)\./.test(a.address)) subnets.add(p.slice(0, 3).join("."));   // ไม่สแกนวงโรงงาน / cloud
    }
    report.push("IP กล่องนี้: " + own.join(", ") + " · สแกนวง: " + [...subnets].map(s => s + ".x").join(", "));
    const found = [], QP = [5000, 5001, 5002, 5007, 5010, 5100, 1025, 502];
    for (const sn of subnets) for (let base = 1; base < 255; base += 32) {
        node.status({ fill: "blue", shape: "ring", text: "หา PLC " + sn + "." + base + "–" + Math.min(254, base + 31) });
        const jobs = [];
        for (let i = base; i < Math.min(255, base + 32); i++) {
            const ip = sn + "." + i; if (own.includes(ip)) continue;
            jobs.push(Promise.all(QP.map(p => portOpen(ip, p, 500).then(ok => ok ? p : null))).then(ps => { ps = ps.filter(Boolean); if (ps.length) found.push({ ip, ports: ps }); }));
        }
        await Promise.all(jobs);
    }
    report.push(found.length ? "เจอเครื่องที่เปิด port: " + found.map(f => f.ip + " [" + f.ports.join(",") + "]").join(" · ") : "ไม่เจอเครื่องที่เปิด port PLC ในวงที่สแกน");
    return found;
}
async function discover() {
    const report = [];
    let hosts = HOST ? [{ ip: HOST, ports: PORTS }] : await findHosts(report);
    for (const h of hosts) {
        const ports = h.ports.concat(PORTS.filter(p => !h.ports.includes(p)));
        for (const port of ports) {
            const protos = port === 502 ? ["MB1", "MB0", "MB255"].concat(PROTOS) : PROTOS;   // บางเครื่องตั้ง SLMP ไว้ที่ port 502
            for (const proto of protos) {
                node.status({ fill: "blue", shape: "ring", text: "ทดสอบ " + h.ip + ":" + port + " " + proto });
                const c = await getConn(h.ip, port, false);
                if (c.dead) { report.push(h.ip + ":" + port + " ต่อไม่ได้ (" + c.why + ")"); break; }
                const r = await readBlock(c, proto, /^MB/.test(proto) ? AREAS_MB[0] : AREAS_MC[0], 0, 10);
                if (r.v) { report.push("✓ " + h.ip + ":" + port + " " + proto + " ใช้ได้"); return { cfg: { host: h.ip, port, proto }, report }; }
                report.push(h.ip + ":" + port + " " + proto + ": " + r.err);
                c.dead = true; try { c.sock.destroy(); } catch (e) {}
                await sleep(250);
            }
            if (HOST && hosts.length === 1 && report.length > 60) break;
        }
    }
    // SLMP แบบ UDP
    for (const h of hosts) for (const port of UDP_PORTS) for (const proto of ["MC3E", "MC3E-ASCII", "MC4E"]) {
        node.status({ fill: "blue", shape: "ring", text: "ทดสอบ UDP " + h.ip + ":" + port + " " + proto });
        const c = await getConn(h.ip, port, true);
        const r = await readBlock(c, proto, AREAS_MC[0], 0, 10);
        if (r.v) { report.push("✓ UDP " + h.ip + ":" + port + " " + proto + " ใช้ได้"); return { cfg: { host: h.ip, port, proto, udp: true }, report }; }
        report.push("UDP " + h.ip + ":" + port + " " + proto + ": " + r.err);
        c.dead = true; try { c.sock.destroy(); } catch (e) {}
    }
    report.push("→ ไม่เจอ: เช็คสาย LAN กล่อง eth0 ↔ PLC, IP วงเดียวกัน, และใน GX Works เปิด SLMP / MC protocol (Open setting: TCP, Binary, port 5000/5100) + เปิด 'Enable online change'");
    return { report };
}

// ---------- อ่านทุกช่วง ----------
async function scanAll(cfg) {
    const blk = isMB(cfg) ? 125 : BLOCK;        // Modbus อ่านได้สูงสุด 125 register / 2000 coil ต่อครั้ง
    const c = await getConn(cfg.host, cfg.port, cfg.udp);
    if (c.dead) return { err: "ต่อไม่ได้ (" + c.why + ")" };
    const lim = context.get("lim") || {}, snap = {};
    for (const a of AREAS) {
        const max = lim[a.dev] != null ? lim[a.dev] : a.words;
        const arr = [];
        for (let s = 0; s < max; s += blk) {
            const n = Math.min(blk, max - s);
            let r = await readBlock(c, cfg.proto, a, s, n);
            if (r.code) {                         // เกินช่วง / ไม่มี device นี้ -> ลองลดขนาด แล้วจำขอบเขตไว้
                let lo = 0, hi = n - 1, best = null;    // หาขอบเขตจริงแบบแบ่งครึ่ง
                while (lo <= hi) { const m = (lo + hi + 1) >> 1; if (m === 0) break; const t = await readBlock(c, cfg.proto, a, s, m); if (t.v) { best = t.v; lo = m + 1; } else hi = m - 1; }
                if (best) arr.push(...best);
                lim[a.dev] = s + (best ? best.length : 0); context.set("lim", lim);
                break;
            }
            if (r.err) return { err: a.dev + s + ": " + r.err };
            arr.push(...r.v);
        }
        snap[a.dev] = arr;
    }
    return { snap };
}

// ---------- สถิติ ----------
function addr(a, i) { return a.hex ? a.dev + hx(i, 1) : a.dev + i; }
function bitAddr(a, w, b) { const n = w * 16 + b; return a.hex ? a.dev + hx(n, 1) : a.dev + n; }
function update(st, snap) {
    const now = Date.now();
    st.n++; st.last = now;
    for (const a of AREAS) {
        const v = snap[a.dev] || [];
        const S = st.dev[a.dev] = st.dev[a.dev] || { first: v.slice(), prev: v.slice(), chg: {}, up: {}, dn: {}, mn: {}, mx: {}, inc1: {}, bchg: {} };
        for (let i = 0; i < v.length; i++) {
            const p = S.prev[i], x = v[i];
            if (p === undefined || p === x) continue;
            if (a.bit) { let d = p ^ x; for (let b = 0; b < 16; b++) if (d & (1 << b)) { const k = i * 16 + b; S.bchg[k] = (S.bchg[k] || 0) + 1; } continue; }
            S.chg[i] = (S.chg[i] || 0) + 1;
            if (x > p) { S.up[i] = (S.up[i] || 0) + 1; if (x - p <= 3) S.inc1[i] = (S.inc1[i] || 0) + 1; } else S.dn[i] = (S.dn[i] || 0) + 1;
            S.mn[i] = Math.min(S.mn[i] != null ? S.mn[i] : p, x); S.mx[i] = Math.max(S.mx[i] != null ? S.mx[i] : p, x);
        }
        S.prev = v.slice();
    }
}
function s16(x) { return x > 32767 ? x - 65536 : x; }
function guess(c, up, dn, inc1, mn, mx) {
    if (up >= 2 && dn === 0 && inc1 >= up * 0.6) return "⭐ Counter? (เพิ่มทีละน้อย ไม่ลด)";
    if (up >= 2 && dn === 0) return "เพิ่มอย่างเดียว (Counter / เวลาสะสม?)";
    if (mx - mn <= 10 && c >= 2) return "ค่าเล็ก สลับไปมา (Status / Step?)";
    if (c >= 3) return "แกว่ง (Analog / Timer / CT?)";
    return "";
}
function summary(st) {
    const rows = [], bits = [], nz = {}, ascii = [];
    const mins = ((st.last - st.t0) / 60000).toFixed(1);
    for (const a of AREAS) {
        const S = st.dev[a.dev]; if (!S) continue;
        const v = S.prev;
        if (!a.bit) {
            for (const k of Object.keys(S.chg)) {
                const i = +k, c = S.chg[i], up = S.up[i] || 0, dn = S.dn[i] || 0;
                const row = { tag: addr(a, i), now: v[i], signed: s16(v[i]), first: S.first[i], min: S.mn[i], max: S.mx[i], changes: c, up, down: dn,
                              guess: guess(c, up, dn, S.inc1[i] || 0, S.mn[i], S.mx[i]) };
                // 32 bit (คำต่ำ i + คำสูง i+1) ถ้าคำถัดไปไม่เป็น 0 หรือคำนี้เคยล้น
                if (v[i + 1]) row.dword = v[i] + v[i + 1] * 65536 + " (" + addr(a, i) + "-" + addr(a, i + 1) + ")";
                row.score = (row.guess.startsWith("⭐") ? 1000 : 0) + (dn === 0 && up > 0 ? 300 : 0) + Math.min(c, 200);
                rows.push(row);
            }
            // ค่าไม่เป็น 0 + ข้อความ ASCII (ชื่อรุ่น / Lot)
            const list = []; let run = "";
            for (let i = 0; i < v.length; i++) {
                if (v[i]) list.push(addr(a, i) + "=" + v[i]);
                const lo = v[i] & 255, hi = v[i] >> 8, pr = ch => ch >= 32 && ch < 127;
                if (v[i] && pr(lo) && (pr(hi) || hi === 0)) { if (!run) run = { at: addr(a, i), s: "" }; run.s += String.fromCharCode(lo) + (hi ? String.fromCharCode(hi) : ""); }
                else { if (run && run.s.replace(/[^A-Za-z]/g, "").length >= 3) ascii.push(run.at + ' "' + run.s + '"'); run = ""; }
            }
            if (list.length) nz[a.dev] = list.length > 400 ? list.slice(0, 400).concat(["... อีก " + (list.length - 400)]) : list;
        } else {
            const on = [];
            for (let w = 0; w < v.length; w++) for (let b = 0; b < 16; b++) if (v[w] & (1 << b)) on.push(bitAddr(a, w, b));
            if (on.length) nz[a.dev + " (ON)"] = on.length > 300 ? on.slice(0, 300).concat(["... อีก " + (on.length - 300)]) : on;
            for (const k of Object.keys(S.bchg)) { const n = +k; bits.push({ tag: bitAddr(a, Math.floor(n / 16), n % 16), now: (v[Math.floor(n / 16)] >> (n % 16)) & 1, toggles: S.bchg[n] }); }
        }
    }
    rows.sort((x, y) => y.score - x.score); rows.forEach(r => delete r.score);
    bits.sort((x, y) => y.toggles - x.toggles);
    const lim = context.get("lim") || {};
    return [
        { topic: MACHINE + " · Tag ที่เปลี่ยน (" + st.n + " รอบ / " + mins + " นาที) · word " + rows.length + " · bit " + bits.length,
          payload: AREAS === AREAS_MB
              ? { note: "Modbus: HR = Holding Register · FX5 ค่าเริ่มต้น HR n = D n · CO = Coil (Y/M) · DI = X · เช็ค MODBUS Device Assignment ใน GX Works3", words: rows.slice(0, 150), bits: bits.slice(0, 150) }
              : { words: rows.slice(0, 150), bits: bits.slice(0, 150) } },
        { topic: MACHINE + " · ค่าไม่เป็น 0 ตอนนี้ + ข้อความ ASCII", payload: { ascii, nonZero: nz, range: lim } },
        null
    ];
}

(async () => {
