            cfg = d.cfg; context.set("cfg", cfg); context.set("lim", {}); context.set("st", null);
            AREAS = isMB(cfg) ? AREAS_MB : AREAS_MC;
        }
        const r = await scanAll(cfg);
        context.set("lastScan", Date.now());
        if (!r.snap) {
            const n = (context.get("fail") || 0) + 1; context.set("fail", n);
            node.status({ fill: "red", shape: "ring", text: cfg.host + ":" + cfg.port + " " + r.err + " (" + n + ")" });
            if (n >= 20) { context.set("cfg", null); context.set("fail", 0); }
            return;
        }
        context.set("fail", 0);
        let st = context.get("st");
        if (!st) st = { t0: Date.now(), n: 0, dev: {} };
        update(st, r.snap); context.set("st", st);
        flow.set("cm08_raw", r.snap); flow.set("cm08_ok", Date.now());
        let nw = 0, nb = 0; for (const k in st.dev) { nw += Object.keys(st.dev[k].chg).length; nb += Object.keys(st.dev[k].bchg).length; }
        node.status({ fill: "green", shape: "dot", text: (cfg.udp ? "UDP " : "") + cfg.proto + " " + cfg.host + ":" + cfg.port + " · รอบ " + st.n + " · word เปลี่ยน " + nw + " · bit เปลี่ยน " + nb });
        if (st.n === 1 || st.n % 24 === 0) node.send(summary(st));     // ส่งสรุปเองรอบแรก และทุก ~2 นาที
    } catch (e) {
        node.status({ fill: "red", shape: "ring", text: String(e.message || e) });
        node.send([null, null, { topic: "error", payload: String(e.stack || e) }]);
    } finally {
        context.set("busy", false);
    }
})();
