// @ts-nocheck
// ===== ดูค่า Tag ที่สนใจแบบสด (จากผลสแกนล่าสุด ไม่ต่อ PLC เพิ่ม) =====
// ใส่ Tag ที่เจอจากสรุปผล แล้ว Deploy · Modbus: "HR100" / "HR100L" / "CO8200" · MC: "D100" = 16 bit · "D100L" = 32 bit (D100 คำต่ำ + D101 คำสูง) · "M98" = bit · "D200S5" = ข้อความ 5 word
const WATCH = ["HR0", "HR1", "HR2", "CO0"];   // *** แก้ตรงนี้ ***
const raw = flow.get("cm08_raw");
if (!raw || Date.now() - (flow.get("cm08_ok") || 0) > 20000) { node.status({ fill: "grey", shape: "ring", text: "ยังไม่มีข้อมูลสแกน" }); return null; }
const HEXDEV = { X: 1, Y: 1, B: 1, W: 1 };
const out = {};
for (const t of WATCH) {
    const m = /^(HR|IR|CO|DI|[A-Z])([0-9A-F]+?)(L|S(\d+))?$/i.exec(String(t).trim());
    if (!m) { out[t] = "รูปแบบไม่ถูก"; continue; }
    const dev = m[1].toUpperCase(), n = parseInt(m[2], HEXDEV[dev] ? 16 : 10), arr = raw[dev];
    if (!arr) { out[t] = "ไม่ได้สแกน " + dev; continue; }
    if (/^(M|X|Y|B|CO|DI)$/.test(dev)) { const w = arr[Math.floor(n / 16)]; out[t] = w == null ? "เกินช่วง" : (w >> (n % 16)) & 1; continue; }
    if (arr[n] == null) { out[t] = "เกินช่วง"; continue; }
    if (m[3] && m[3].toUpperCase() === "L") out[t] = arr[n] + (arr[n + 1] || 0) * 65536;
    else if (m[4]) { let s = ""; for (let i = 0; i < +m[4]; i++) { const w = arr[n + i] || 0; s += String.fromCharCode(w & 255, w >> 8); } out[t] = s.replace(/\0/g, "").trim(); }
    else out[t] = arr[n];
}
node.status({ fill: "green", shape: "dot", text: Object.keys(out).map(k => k + "=" + out[k]).join("  ").slice(0, 120) });
msg.payload = out; msg.topic = "CM-008 Tag สด " + new Date().toLocaleTimeString("en-GB");
return msg;
